var LIMIT = 4e6;
function lineDiff(before, after) {
	const a = before.replace(/\n$/, "").split("\n");
	const b = after.replace(/\n$/, "").split("\n");
	let start = 0;
	while (start < a.length && start < b.length && a[start] === b[start]) start++;
	let endA = a.length;
	let endB = b.length;
	while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) endA--, endB--;
	const head = a.slice(0, start).map((text) => ({
		op: "eq",
		text
	}));
	const tail = a.slice(endA).map((text) => ({
		op: "eq",
		text
	}));
	const x = a.slice(start, endA);
	const y = b.slice(start, endB);
	if (x.length * y.length > LIMIT) return [
		...head,
		...x.map((text) => ({
			op: "del",
			text
		})),
		...y.map((text) => ({
			op: "add",
			text
		})),
		...tail
	];
	const dp = Array.from({ length: x.length + 1 }, () => new Uint32Array(y.length + 1));
	for (let i = x.length - 1; i >= 0; i--) for (let j = y.length - 1; j >= 0; j--) dp[i][j] = x[i] === y[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
	const mid = [];
	let i = 0;
	let j = 0;
	while (i < x.length && j < y.length) if (x[i] === y[j]) mid.push({
		op: "eq",
		text: x[i]
	}), i++, j++;
	else if (dp[i + 1][j] >= dp[i][j + 1]) mid.push({
		op: "del",
		text: x[i++]
	});
	else mid.push({
		op: "add",
		text: y[j++]
	});
	while (i < x.length) mid.push({
		op: "del",
		text: x[i++]
	});
	while (j < y.length) mid.push({
		op: "add",
		text: y[j++]
	});
	return [
		...head,
		...mid,
		...tail
	];
}
